-- =============================================================================
-- 99 · Textes des 3 annuaires prioritaires (pages locales : docs/seo/PAGES-LOCALES.md), en BROUILLON.
-- Rédigés par l'assistant (author_kind = 'agent') : un éditeur humain les relit, les soumet et les approuve (règle 1).
-- Aucun chiffre réglementaire écrit en dur : les seuils renvoient à la fiche officielle (règle 6, sources datées).
-- Idempotent : mot-clé rattaché seulement s'il manque ; version créée seulement si la page n'en a aucune.
-- =============================================================================

-- Mots-clés nationaux (Semrush FR, 11/11/2026, docs/seo/PAGES-LOCALES.md)
insert into public.keyword_targets (site_id, keyword, volume, intent, cluster, source, refreshed_at) values
  ('10000000-0000-4000-a000-000000000001', 'expert comptable', 27100, 'commercial', 'experts-comptables', 'semrush', '2026-11-11'),
  ('10000000-0000-4000-a000-000000000001', 'commissaire aux comptes', 6600, 'commercial', 'commissaires-aux-comptes', 'semrush', '2026-11-11'),
  ('10000000-0000-4000-a000-000000000001', 'cabinet de recrutement', 4400, 'commercial', 'cabinets-recrutement-finance', 'semrush', '2026-11-11')
on conflict (site_id, keyword) do nothing;

create or replace function pg_temp.annuaire(p_slug text, p_kw text, p_meta_title text, p_meta_desc text, p_h1 text,
  p_summary text, p_body text, p_faq jsonb, p_sources jsonb)
returns void language plpgsql as $$
declare site constant uuid := '10000000-0000-4000-a000-000000000001'; iid uuid; kid uuid; vid uuid; s jsonb;
begin
  select id into iid from public.content_items where site_id = site and type = 'provider_directory' and slug = p_slug;
  if iid is null then return; end if;
  -- Mot-clé principal (une page par mot-clé)
  select id into kid from public.keyword_targets where site_id = site and keyword = p_kw;
  if kid is not null and not exists (select 1 from public.content_items where primary_keyword_id = kid)
     and (select primary_keyword_id from public.content_items where id = iid) is null then
    update public.content_items set primary_keyword_id = kid where id = iid;
    update public.keyword_targets set target_content_id = iid, status = 'in_progress' where id = kid and target_content_id is null;
    update public.seo_briefs set primary_keyword = p_kw where content_item_id = iid;
  end if;
  -- Brouillon, seulement si aucune version n'existe
  if exists (select 1 from public.content_versions where content_item_id = iid) then return; end if;
  insert into public.content_versions (content_item_id, version_no, meta_title, meta_description, h1, summary, body, faq, author_kind)
  values (iid, 0, p_meta_title, p_meta_desc, p_h1, p_summary, p_body, p_faq, 'agent') returning id into vid;
  for s in select * from jsonb_array_elements(p_sources) loop
    insert into public.content_sources (content_version_id, url, title, accessed_at, excerpt)
    values (vid, s->>'url', s->>'title', (s->>'accessed_at')::date, s->>'excerpt');
  end loop;
end;
$$;

